class PredictionModel(nn.Module):


    def __init__(self, input_shape, hidden_shapes, output_shape=1, **kwargs):

        super(PredictionModel, self).__init__()

        self.time_conditioning = kwargs['time_conditioning'] if kwargs.get('time_conditioning') else False
        self.leaky = kwargs['leaky']
        self.trelu = kwargs['trelu']
        if self.time_conditioning:

            self.leaky = kwargs['leaky'] if kwargs.get('leaky') else False

        use_time2vec = kwargs['use_time2vec'] if kwargs.get('use_time2vec') else False
        self.regress = kwargs['task'] == 'regression' if kwargs.get('task') else False
        self.time_shape = 1

        if use_time2vec:
            self.time_shape = 8
            self.time2vec = Time2Vec(1, 8)
        else:
            self.time_shape = 1
            self.time2vec = None

        self.layers = nn.ModuleList()
        self.relus = nn.ModuleList()

        self.input_shape = input_shape
        self.hidden_shapes = hidden_shapes
        self.output_shape = output_shape

        if len(self.hidden_shapes) == 0: # single layer NN, no TReLU

            self.layers.append(nn.Linear(input_shape, output_shape))
            self.relus.append(nn.LeakyReLU())

        else:

            self.layers.append(nn.Linear(self.input_shape, self.hidden_shapes[0]))
            if self.time_conditioning and self.trelu:
                self.relus.append(TimeReLU(data_shape=self.hidden_shapes[0], time_shape=self.time_shape, leaky=self.leaky))
            else:
                if self.leaky:
                    self.relus.append(nn.LeakyReLU())
                else:
                    self.relus.append(nn.ReLU())

            for i in range(len(self.hidden_shapes) - 1):

                self.layers.append(nn.Linear(self.hidden_shapes[i], self.hidden_shapes[i+1]))
                if self.time_conditioning and self.trelu:
                    self.relus.append(TimeReLU(data_shape=self.hidden_shapes[i+1], time_shape=self.time_shape, leaky=self.leaky))
                else:
                    if self.leaky:
                        self.relus.append(nn.LeakyReLU())
                    else:
                        self.relus.append(nn.ReLU())


            self.layers.append(nn.Linear(self.hidden_shapes[-1], self.output_shape))

        self.apply(init_weights)



    def forward(self, X, times=None, logits=False):

        if self.time_conditioning:
            X = torch.cat([X, times.view(-1, 1)], dim=-1)

        if self.time2vec is not None:
            times = self.time2vec(times)

        if self.time_conditioning and self.trelu:
            X = self.relus[0](self.layers[0](X), times)
        else:
            X = self.relus[0](self.layers[0](X))

        for i in range(1, len(self.layers)-1):

            X = self.layers[i](X)
            if self.time_conditioning and self.trelu:
                X = self.relus[i](X, times)
            else:
                X = self.relus[i](X)

        X = self.layers[-1](X)
        #if self.regress:
        #   X = torch.relu(X)
        #else:
        #   X = torch.softmax(X,dim=1)

        if not logits:
            if self.output_shape > 1:
                X = torch.softmax(X, dim=-1)
            else:
                X = torch.sigmoid(X)

        return X        

def classification_loss(Y_pred, Y):
    # print(Y_pred)
    # print(Y_pred)
    Y_new = torch.zeros_like(Y_pred)
    Y_new = Y_new.scatter(1,Y.view(-1,1),1.0)
    # print(Y_new * torch.log(Y_pred+ 1e-15))
    return  -1.*torch.mean((Y_new * torch.log(Y_pred+ 1e-15)),dim=1)

def reconstruction_loss(x,y):
    x_1 = x.view(x.size(0),-1)
    y_1 = y.view(y.size(0),-1)
    return torch.sum((x_1-y_1)**2,dim=1) 

def binary_classification_loss(Y_pred,Y):
    # print(Y_pred.size(),Y.size())
    Y_pred = Y_pred.squeeze()
    if torch.max(Y_pred) > 1.0 or torch.min(Y_pred) < 0.0:   # Nice!
        Y_pred = torch.sigmoid(Y_pred)
    # print(Y_pred.size(),Y.size())
    return -(Y * torch.log(Y_pred + 1e-9) + (1 - Y) * torch.log(1 - Y_pred + 1e-9))

def adversarial_finetune(X, U, Y, delta, classifier, classifier_optimizer,classifier_loss_fn,delta_lr=0.1,delta_clamp=0.15,delta_steps=10,lambda_GI=0.5,writer=None,step=None,string=None, verbose=False):

    classifier_optimizer.zero_grad()

    delta.requires_grad_(True)

    # This block of code computes delta adversarially
    d1 = delta.detach().cpu().numpy()
    for ii in range(delta_steps):
        delta = delta.clone().detach()
        delta.requires_grad_(True)
        U_grad = U.clone() - delta
        U_grad.requires_grad_(True)
        Y_pred = classifier(X, U_grad, logits=True)
        if len(Y.shape)>1 and Y.shape[1] > 1:
            Y_true = torch.argmax(Y, 1).view(-1,1).float()

        partial_logit_pred_t = []
        if len(Y_pred.shape)<2 or Y_pred.shape[1] < 2:
            partial_Y_pred_t = torch.autograd.grad(Y_pred, U_grad, grad_outputs=torch.ones_like(Y_pred), retain_graph=True,create_graph=True)[0]
        else:           
            for idx in range(Y_pred.shape[1]):
                logit = Y_pred[:,idx].view(-1,1)
                partial_logit_pred_t.append(torch.autograd.grad(logit, U_grad, grad_outputs=torch.ones_like(logit), create_graph=True)[0])


            partial_Y_pred_t = torch.cat(partial_logit_pred_t, 1)



        Y_pred = Y_pred + delta * partial_Y_pred_t

        if len(Y_pred.shape)>1 and Y_pred.shape[1] > 1:
            Y_pred = torch.softmax(Y_pred,dim=-1)
        loss = classifier_loss_fn(Y_pred,Y).mean()
        partial_loss_delta = torch.autograd.grad(loss, delta, grad_outputs=torch.ones_like(loss), retain_graph=True)[0]
        delta = delta + delta_lr*partial_loss_delta

        if delta.size(0) > 1:
            delta[delta != delta] = 0.
            if torch.norm(partial_loss_delta) < 1e-3*delta.size(0) :
                    break
        else:
            if torch.norm(partial_loss_delta) < 1e-3 or delta > delta_clamp or delta < -1*delta_clamp:
                break
# 
    delta = delta.clamp(-1*delta_clamp, delta_clamp).detach().clone()
    d2 = delta.detach().cpu().numpy()
    if writer is not None:
        writer.add_scalar(string,torch.abs(delta).mean(),step)
        writer.add_scalar(string+"_grad",torch.abs(partial_loss_delta).mean(),step)

    # This block of code actually optimizes our model
    U_grad = U.clone() - delta
    U_grad.requires_grad_(True)
    Y_pred = classifier(X, U_grad, logits=True)

    partial_logit_pred_t = []

    if len(Y_pred.shape)<2 or Y_pred.shape[1] < 2:
        partial_Y_pred_t = torch.autograd.grad(Y_pred, U_grad, grad_outputs=torch.ones_like(Y_pred), create_graph=True)[0]
    else:
        for idx in range(Y_pred.shape[1]):
            logit = Y_pred[:,idx].view(-1,1)
            partial_logit_pred_t.append(torch.autograd.grad(logit, U_grad, grad_outputs=torch.ones_like(logit), retain_graph=True)[0])
        partial_Y_pred_t = torch.cat(partial_logit_pred_t, 1)

    Y_pred = Y_pred + delta * partial_Y_pred_t
    if len(Y_pred.shape)>1 and Y_pred.shape[1] > 1:
        Y_pred = torch.softmax(Y_pred,dim=-1)
    Y_orig_pred = classifier(X,U)

    # TODO INVERT LAMBDA for HOUSE, ELEC
    pred_loss = classifier_loss_fn(Y_pred,Y).mean() + lambda_GI*classifier_loss_fn(Y_orig_pred,Y).mean() 

    pred_loss.backward()

    classifier_optimizer.step()

    return pred_loss, delta

